SELECT gen_random_uuid()::text, 'formula', '$K_c$', 'Equilibrium Constant', '$K_c = \frac{[C]^c[D]^d}{[A]^a[B]^b},\qquad K_p = K_c(RT)^{\Delta n}$', NULL, 'For aA + bB ⇌ cC + dD: the ratio that is fixed at a given temperature.', '[{"symbol":"$[\\ ]$","meaning":"equilibrium molar concentrations","unit":"$\\text{mol/L}$"},{"symbol":"$\\Delta n$","meaning":"moles of gas products minus reactants","unit":null}]'::jsonb, 'Leave out pure solids and liquids. If Q < K the reaction goes forward.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Chemistry for Engineers' AND t."subject" = 'ESAS' AND s."normKey" = 'equilibrium, acids and bases' AND s."active"), NULL, true, 'PENDING', now(), now()
