SELECT gen_random_uuid()::text, 'formula', '$\Delta G$', 'Gibbs Free Energy', '$\Delta G = \Delta H - T\Delta S;\qquad \Delta G^\circ = -RT\ln K$', '$\text{kJ}$', 'Whether a reaction runs on its own (ΔG < 0), and how far.', '[{"symbol":"$\\Delta H$","meaning":"enthalpy change","unit":"$\\text{kJ}$"},{"symbol":"$\\Delta S$","meaning":"entropy change","unit":"$\\text{kJ/K}$"},{"symbol":"$T$","meaning":"absolute temperature","unit":"$\\text{K}$"},{"symbol":"$K$","meaning":"equilibrium constant","unit":null}]'::jsonb, 'With ΔH > 0 and ΔS > 0 it becomes spontaneous above T = ΔH/ΔS.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Chemistry for Engineers' AND t."subject" = 'ESAS' AND s."normKey" = 'thermochemistry and energy' AND s."active"), NULL, false, 'PENDING', now(), now()
