SELECT gen_random_uuid()::text, 'formula', '$k$', 'Arrhenius Equation', '$k = Ae^{-E_a/RT};\qquad \ln\frac{k_2}{k_1} = \frac{E_a}{R}\left(\frac{1}{T_1} - \frac{1}{T_2}\right)$', NULL, 'How a reaction''s rate constant rises with temperature.', '[{"symbol":"$E_a$","meaning":"activation energy","unit":"$\\text{J/mol}$"},{"symbol":"$R$","meaning":"gas constant, 8.314 J/(mol·K)","unit":"$\\text{J/(mol}\\cdot\\text{K)}$"},{"symbol":"$T$","meaning":"absolute temperature","unit":"$\\text{K}$"},{"symbol":"$A$","meaning":"frequency factor","unit":null}]'::jsonb, 'A rough rule: rates double for every 10 °C near room temperature (Eₐ ≈ 50 kJ/mol).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Chemistry for Engineers' AND t."subject" = 'ESAS' AND s."normKey" = 'thermochemistry and energy' AND s."active"), NULL, true, 'PENDING', now(), now()
