SELECT gen_random_uuid()::text, 'formula', '$E^\circ_{cell}$', 'Standard Cell Potential', '$E^\circ_{cell} = E^\circ_{cathode} - E^\circ_{anode}$', '$\text{V}$', 'A galvanic cell''s voltage from the reduction potentials of its two halves.', '[{"symbol":"$E^\\circ$","meaning":"standard reduction potentials","unit":"$\\text{V}$"}]'::jsonb, 'Daniell cell: 0.34 − (−0.76) = 1.10 V. Positive E° means spontaneous.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Chemistry for Engineers' AND t."subject" = 'ESAS' AND s."normKey" = 'electrochemistry and batteries' AND s."active"), NULL, false, 'PENDING', now(), now()
